"""
Where does the wall-clock time of a viewer run go?

    export DISPLAY=:0 XAUTHORITY=...
    python experiments/viewer_profile.py episode [--ticks 600]       # a viewer episode (staging, idle test source) under cProfile
    python -m cProfile -o /tmp/launcher.prof experiments/combined_controller.py       # the interactive launcher, bench mode:
        (with CC_BENCH_FRAMES=600 CC_BENCH_KEYS="5-45:UP,45-95:SPACE,..." in the environment)
    python experiments/viewer_profile.py report /tmp/launcher.prof

The loop's own timers (printed as "BENCH ...") give the split between physics, camera renders, the main view, HUD / insets and buffer swap;
cProfile adds the rest (Python code of the sources, observation building, logging...) and the per-function C time. cProfile slows
Python code down a little, so the timers are the reference for the split and the profile for attribution.
"""

import cProfile
import os
import pstats
import sys
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))

# (label, file fragment, function-name fragment, only calls made from this caller's file fragment or None). pstats names C functions
# "<built-in method mujoco._functions.mj_step>" in file "~"; the time of a C function is its own time, of a Python one the cumulative time.
GROUPS = [
    ("physics: mj_step (12 per tick)", "~", "mujoco._functions.mj_step", None),
    ("camera renders (CameraRig.render, policy + inset rigs)", "cameras.py", "render", None),
    ("  of which mjr_readPixels (the GPU wait)", "~", "mujoco._render.mjr_readPixels", "cameras.py"),
    ("viewer frame() in total", "glfw_viewer.py", "frame", None),
    ("  main view: mjr_render", "~", "mujoco._render.mjr_render", "glfw_viewer.py"),
    ("  HUD + insets: bitmap text + mjr_drawPixels", "~", "mujoco._render.mjr_drawPixels", "glfw_viewer.py"),
    ("  buffer swap", "glfw", "swap_buffers", None),
    ("  event poll", "glfw", "poll_events", None),
    ("frame pacing sleep", "~", "time.sleep", None),
    ("on_tick hook (runner: log, contacts, clearance, success)", "episode_runner.py", "on_tick", None),
    ("staging source step", "staging_source.py", "step", None),
    ("control loop total (run_loop)", "control_loop.py", "run_loop", None),
]


def report(stats_path, top=18):
    st = pstats.Stats(stats_path)
    total = st.total_tt
    print(f"\ntotal profiled time {total:.1f} s")
    ents = st.stats      # (file, line, name) -> (cc, nc, tottime, cumtime, callers{(file, line, name): (cc, nc, tt, ct)})

    def cum(file_frag, name_frag, caller_frag):
        t = 0.0
        for (f, l, n), v in ents.items():
            if file_frag not in f or name_frag not in n:
                continue
            if caller_frag is None:
                t += v[2] if f == "~" else v[3]
            else:
                t += sum(c[3] for (cf, cl, cn), c in v[4].items() if caller_frag in cf)
        return t
    print(f"{'component':58s} {'cumulative s':>12s} {'% of total':>10s}")
    for label, ff, nf, cf in GROUPS:
        t = cum(ff, nf, cf)
        print(f"{label:58s} {t:12.2f} {100 * t / total:9.1f}%")
    print(f"\ntop {top} by own time (tottime):")
    rows = sorted(((v[2], v[1], f"{n} ({Path(f).name}:{l})") for (f, l, n), v in ents.items()), reverse=True)[:top]
    for tt, nc, name in rows:
        print(f"  {tt:8.2f} s  {100 * tt / total:5.1f}%  {nc:8d} calls  {name}")


def episode(ticks, loop_cfg=None, viewer_cfg=None):
    os.environ.pop("MUJOCO_GL", None)
    from src.episode_runner import run_episode
    from src.episode_test_sources import make_idle_source
    from src.glfw_viewer import make_glfw_viewer
    from src.task_beaker_hotplate import load_task
    sim = load_task(cameras=True)
    viewer = make_glfw_viewer(sim.model, sim.data, {"win": (1280, 960), "vsync": 0, "view_shadows": False, "shadowsize": None, "hud": True, "insets": True,
                                                    "record": False, "snapshot_every": 0.0, "snapshot_dir": None, "bench_snap_dir": None,
                                                    "bench_snap_frame": 15, "finish": False, "roundrobin": True,
                                                    "record_fps": 62.5, "has_teleop": False, **(viewer_cfg or {})})
    viewer["set_held"](viewer["key_down"])
    prof = cProfile.Profile()
    prof.enable()
    run_episode(lambda m, d: make_idle_source(), sim.model, sim.data, viewer=viewer, held=viewer["key_down"], loop_cfg={"bench_frames": ticks, **(loop_cfg or {})})
    prof.disable()
    viewer["close"]()
    out = "/tmp/episode_viewer.prof"
    prof.dump_stats(out)
    report(out)


if __name__ == "__main__":
    if sys.argv[1] == "episode":
        # --loop key=value ... and --viewer key=value ...: overrides of the loop cfg / viewer cfg (values are Python literals)
        import ast
        def kv(flag):
            if flag not in sys.argv:
                return {}
            out = {}
            for a in sys.argv[sys.argv.index(flag) + 1:]:
                if a.startswith("--"):
                    break
                out[a.split("=")[0]] = ast.literal_eval(a.split("=", 1)[1])
            return out
        episode(int(sys.argv[sys.argv.index("--ticks") + 1]) if "--ticks" in sys.argv else 600, kv("--loop"), kv("--viewer"))
    else:
        report(sys.argv[2])
